export const audioViewTitle='Wisdom of China';
export function audioViewHTML({mode='normal',layout='compact'}={}){
  const audio='<audio preload="auto" src="https://ucontent.unipus.cn/offline-recognition/audio-view.wav"></audio>';
  const player=layout==='platform'?`<div class="question-audio">${audio}<div class="audio-control audio-control-bar"><div class="controller"><div class="controllerLeft"><div class="btn-play"><span class="anticon anticon-play icon-audio-action" role="img">▶</span></div></div><div class="controller-progress"><div class="sliderWrap"><div class="progress-slider"><div class="progress-slider-track progress-slider-track-0"></div><div class="progress-slider-track progress-slider-track-1"></div><div class="progress-slider-thumb progress-slider-thumb-0" role="slider"></div></div></div><div class="timeBar"><span class="startTime">00:00</span><span class="endTime">01:19</span></div></div><div class="controller-btn-group"><div class="playSpeed">1.0x</div><span class="volume-control-icon volume">◖</span></div></div></div></div>`:`<div class="audio-box">${audio}<span class="audio-play anticon anticon-play-circle" role="button" aria-label="播放">▶</span><div class="ant-slider"><div class="ant-slider-handle" role="slider" aria-label="音频进度"></div></div><span>1.0x</span><span class="volume">◖</span></div>`;
  return `<!doctype html><html><body><style>
    body{font:15px Arial;margin:20px}.audio-box{width:400px;height:72px;border:1px solid #ddd;border-radius:18px;display:flex;align-items:center;gap:18px;padding:0 24px;box-sizing:border-box}audio{display:none}.audio-play{display:block;width:48px;height:48px;border-radius:50%;background:#222;color:white;cursor:pointer;text-align:center;line-height:48px}.ant-slider{position:relative;width:177px;height:12px;background:#ddd;cursor:pointer}.ant-slider-handle{position:absolute;top:1px;left:0;width:10px;height:10px;background:#47f;transform:translateX(-50%);border-radius:50%}.volume{width:40px}.volume .ant-slider{width:40px}article{margin-top:40px;max-width:600px;background:#faf2d8;padding:24px}
    .question-audio{width:1100px;max-width:100%}.audio-control{width:400px;height:72px;border:1px solid #ddd;border-radius:18px;box-sizing:border-box}.controller{display:flex;align-items:center;height:71px}.controllerLeft{width:95px;flex-shrink:0;display:flex;justify-content:center;align-items:center}.btn-play{width:55px;height:55px;border-radius:50%;background:#222;color:white;cursor:pointer;display:grid;place-items:center}.controller-progress{width:192px;height:71px;display:flex;flex-direction:column;justify-content:center;flex-shrink:0}.sliderWrap{width:192px;height:10px;padding:0 5px;box-sizing:border-box}.progress-slider{width:182px;height:10px;position:relative;cursor:pointer}.progress-slider-track{position:absolute;top:3px;left:0;width:100%;height:3px;background:#ddd}.progress-slider-thumb{position:absolute;top:0;left:0;width:10px;height:10px;transform:translateX(-50%);border-radius:50%;background:#47f;z-index:1}.timeBar{display:flex;justify-content:space-between;height:24px;font-size:11px;color:#999}.controller-btn-group{width:112px;display:flex;gap:14px;justify-content:center;align-items:center}.playSpeed{font-size:11px}
    ${mode==='bounded-thumb'?'.progress-slider-thumb{transform:none}':''}
    ${mode==='moving-controls'?'.audio-control{pointer-events:none}.btn-play,.progress-slider{pointer-events:auto}.btn-play{animation:audio-button-motion .2s linear infinite alternate}@keyframes audio-button-motion{from{transform:translateX(-2px)}to{transform:translateX(2px)}}':''}
    </style><header><div class="pc-break-crumb"><span class="pc-break-crumb-text">English Book</span><span class="pc-break-crumb-text">Choosing your own path</span><span class="pc-break-crumb-text">${audioViewTitle}</span></div><div class="pc-header-tab-activity">${audioViewTitle}</div><div class="pc-task pc-header-task-activity">${audioViewTitle}</div></header>
    <main class="layout-container"><div class="abs-direction">Listen to Wisdom of China.</div>${player}<article><h1>Wisdom of China</h1><p>Mass entrepreneurship and innovation</p><p>In 2014, China launched its mass entrepreneurship and innovation initiative to promote technological innovation and encourage industrial growth.</p></article></main>
    <script>
      const audio=document.querySelector('audio'),button=document.querySelector('.audio-play,.btn-play'),track=document.querySelector('.ant-slider,.progress-slider'),thumb=track.querySelector('.ant-slider-handle,.progress-slider-thumb'),mode=${JSON.stringify(mode)};
      window.playClicks=0;window.dragStarts=0;window.nativeEnds=0;window.syntheticEnds=0;window.seekRequests=[];window.playerActions=[];window.pointerTrusted=[];
      window.audioEvents=[];for(const type of ['play','playing','pause','seeking','seeked','waiting','ended'])audio.addEventListener(type,()=>window.audioEvents.push({type,time:audio.currentTime,clock:Math.round(performance.now())}));
      window.tailPauses=0;if(mode==='tail-pause-once'||mode==='tail-pause-repeat')audio.addEventListener('playing',()=>{if(mode==='tail-pause-once'&&window.tailPauses)return;const start=audio.currentTime;const pauseAtTail=()=>{if(audio.ended||audio.paused)return;if(audio.duration-audio.currentTime<=.7&&audio.currentTime-start>=.06){window.tailPauses++;audio.pause();}else setTimeout(pauseAtTail,20);};setTimeout(pauseAtTail,100);});
      audio.addEventListener('ended',event=>{if(event.isTrusted)window.nativeEnds++;else window.syntheticEnds++;});
      audio.addEventListener('timeupdate',()=>{const ratio=audio.currentTime/(audio.duration||1);thumb.style.left=mode==='bounded-thumb'?ratio*(track.clientWidth-thumb.offsetWidth)+'px':ratio*100+'%';});
      button.onclick=()=>{window.playClicks++;window.playerActions.push({kind:audio.paused?'play':'pause',time:audio.currentTime});if(mode==='blocked')return;if(audio.paused){audio.play();if(mode==='popup')document.querySelector('main').insertAdjacentHTML('beforeend','<fieldset><legend>Choose the answer.</legend><input type="radio" name="late">True</fieldset>');}else audio.pause();};
      let dragging=false;
      function seek(event){if(mode==='inert')return;const box=track.getBoundingClientRect(),inset=mode==='bounded-thumb'?thumb.offsetWidth/2:0;audio.currentTime=Math.max(0,Math.min(1,(event.clientX-box.left-inset)/(box.width-inset*2)))*audio.duration;}
      track.addEventListener('mousedown',event=>{window.dragStarts++;window.pointerTrusted.push(event.isTrusted);window.playerActions.push({kind:'drag',paused:audio.paused,time:audio.currentTime});audio.pause();dragging=true;seek(event);});
      document.addEventListener('mousemove',event=>{if(dragging)seek(event);});document.addEventListener('mouseup',event=>{if(!dragging)return;seek(event);dragging=false;window.seekRequests.push(audio.currentTime);});
      if(mode==='ghost')for(let index=0;index<4;index++){const wrap=document.createElement('div');wrap.className='ant-modal-wrap';wrap.style.cssText='position:fixed;inset:0;z-index:'+(1000+index);wrap.innerHTML='<div class="ant-modal ant-modal-hidden" hidden></div>';document.body.append(wrap);}
      if(mode==='dialog'){const wrap=document.createElement('div');wrap.className='ant-modal-wrap';wrap.style.cssText='position:fixed;inset:0;z-index:1000';wrap.innerHTML='<div class="ant-modal" role="dialog" style="background:white;padding:30px">确认其他操作<button onclick="window.unrelatedClicks=(window.unrelatedClicks||0)+1">确认</button></div>';document.body.append(wrap);}
    </script></body></html>`;
}

export function audioViewWav(duration=79){
  const rate=8000,length=Math.round(duration*rate)*2,bytes=Buffer.alloc(44+length);
  bytes.write('RIFF',0);bytes.writeUInt32LE(36+length,4);bytes.write('WAVEfmt ',8);bytes.writeUInt32LE(16,16);bytes.writeUInt16LE(1,20);bytes.writeUInt16LE(1,22);bytes.writeUInt32LE(rate,24);bytes.writeUInt32LE(rate*2,28);bytes.writeUInt16LE(2,32);bytes.writeUInt16LE(16,34);bytes.write('data',36);bytes.writeUInt32LE(length,40);return bytes;
}
